WHERE d.company_id = #{f.companyId}

	AND d.distributor_self = #{f.distributorSelfEq}


	AND d.is_distributor = #{f.isDistributorEq}


	AND d.merchant_id = #{f.merchantIdEq}


	AND d.wechat_work_department_id = 0


	AND d.distributor_id IN
	#{id}


	AND d.name LIKE CONCAT('%', #{f.nameContains}, '%')


	AND d.shop_code LIKE CONCAT('%', #{f.shopCodeContains}, '%')


	AND d.open_divided = #{f.openDivided}


	AND d.province = #{f.provinceEq}


	AND d.city = #{f.cityEq}


	AND d.area = #{f.areaEq}


	AND d.province LIKE CONCAT('%', #{f.provinceContains}, '%')


	AND d.city LIKE CONCAT('%', #{f.cityContains}, '%')


	AND d.area LIKE CONCAT('%', #{f.areaContains}, '%')


	AND d.mobile = #{f.mobileExact}


	AND m.merchant_name LIKE CONCAT('%', #{f.merchantNameLike}, '%')


	AND d.distribution_type = #{f.distributionType}


	AND d.payment_subject = #{f.paymentSubject}


	AND d.distributor_category_id = #{f.distributorCategoryIdEq}


	AND d.is_valid IN
	#{v}


	AND d.is_valid = #{f.isValid}


	AND d.offline_aftersales_other = 1


	AND d.distributor_id <> #{f.distributorIdNeq}


	AND d.distributor_id IN
	#{id}


	AND 1 = 0
